const expandedAuthoredIslands: AuthoredIsland[] = [
  ...baseAuthoredIslands.map((island) => {
    const deepening = deepenedNarratives[island.id]
    if (!deepening) return island
    const outcomes = Object.fromEntries(Object.entries(island.outcomes).map(([choiceId, branches]) => {
      const additions = deepening.outcomes[choiceId]
      return [choiceId, {
        success: { ...branches.success, aftermath: `${branches.success.aftermath}\n\n${additions.success}` },
        failure: { ...branches.failure, aftermath: `${branches.failure.aftermath}\n\n${additions.failure}` },
      }]
    }))
    return {
      ...island,
      scene: deepening.scene ?? island.scene,
      introduction: `${island.introduction}\n\n${deepening.arrival}`,
      outcomes,
    }
  }),
  ...companionSagaIslands,
]

export const authoredIslands: AuthoredIsland[] = expandedAuthoredIslands.map((island) => {
  const literary = islandLiteraryPassA[island.id]
  if (!literary) return island
  // Keep the original second narrative layer as a later observation rather than
  // replacing it with a shorter arrival passage from the literary pass.
  const outcomes = Object.fromEntries(Object.entries(island.outcomes).map(([choiceId, branches]) => [choiceId, {
    success: {
      ...branches.success,
      aftermath: `${branches.success.aftermath}\n\n${literary.successEpilogue}`,
    },
    failure: {
      ...branches.failure,
      aftermath: `${branches.failure.aftermath}\n\n${literary.failureEpilogue}`,
    },
  }]))
  return {
    ...island,
    ...literary,
    introduction: `${literary.introduction}\n\n${island.introduction}`,
    outcomes,
  }
})

export const authoredIslandByEncounter = new Map(authoredIslands.map((island) => [island.encounterId, island]))

export function islandOutcomeNarrative(encounterId: string, choiceId: string, success: boolean) {
  const outcome = authoredIslandByEncounter.get(encounterId)?.outcomes[choiceId]
  return outcome?.[success ? 'success' : 'failure']
}
